pub fn showGroup(lo: u32, hi: u32) bool {
    var idx: ?usize = null;
    for (z3d.g_hidden_groups.items, 0..) |h, i| {
        if (h.lo == lo and h.hi == hi) {
            idx = i;
            break;
        }
    }
    const i = idx orelse return false;
    const entry = z3d.g_hidden_groups.items[i];

    const cur_verts = z3d.g_edit_verts orelse return false;
    const cur_source = model_source.verts() orelse return false;
    const cur_count = z3d.g_edit_count;
    const need = @as(usize, cur_count) * 8;
    if (cur_verts.len < need or cur_source.len < need) return false;
    const cur_groups = z3d.captureFaceGroups() orelse return false;
    defer std.heap.c_allocator.free(cur_groups);
    const cur_colors = z3d.collectCurrentFaceColors() orelse return false;
    defer std.heap.c_allocator.free(cur_colors);
    const cur_logical_ids = model_source.renderCornerLogicalIds();
    if (cur_logical_ids) |rows| if (rows.len != cur_count) return false;
    const has_logical_topology = entry.logical_ids != null or cur_logical_ids != null;
    if (has_logical_topology and ((cur_count > 0 and cur_logical_ids == null) or entry.logical_ids == null)) return false;
    const logical_vertex_count = @max(model_source.logicalVertexCount(), entry.logical_vertex_count);
    const cur_materials = std.heap.c_allocator.alloc(u32, cur_count / 3) catch return false;
    defer std.heap.c_allocator.free(cur_materials);
    for (cur_materials, 0..) |*material, face| material.* = model_source.faceMaterialOf(@intCast(face));
    var current_semantics = z3d.captureFaceSemantics(cur_count / 3) orelse return false;
    defer current_semantics.deinit();

    var out: std.ArrayListUnmanaged(f32) = .empty;
    defer out.deinit(std.heap.c_allocator);
    if (!z3d.appendFloats(&out, cur_verts[0 .. @as(usize, cur_count) * 8]) or !z3d.appendFloats(&out, entry.verts)) {
        return false;
    }
    var source_out: std.ArrayListUnmanaged(f32) = .empty;
    defer source_out.deinit(std.heap.c_allocator);
    if (!z3d.appendFloats(&source_out, cur_source[0..need]) or !z3d.appendFloats(&source_out, entry.source_verts)) return false;
    var groups: std.ArrayListUnmanaged(u32) = .empty;
    defer groups.deinit(std.heap.c_allocator);
    groups.appendSlice(std.heap.c_allocator, cur_groups) catch return false;
    groups.appendSlice(std.heap.c_allocator, entry.groups) catch return false;
    var materials: std.ArrayListUnmanaged(u32) = .empty;
    defer materials.deinit(std.heap.c_allocator);
    materials.appendSlice(std.heap.c_allocator, cur_materials) catch return false;
    materials.appendSlice(std.heap.c_allocator, entry.materials) catch return false;
    var semantic_regions: std.ArrayListUnmanaged(u32) = .empty;
    defer semantic_regions.deinit(std.heap.c_allocator);
    semantic_regions.appendSlice(std.heap.c_allocator, current_semantics.regions) catch return false;
    semantic_regions.appendSlice(std.heap.c_allocator, entry.semantic_regions) catch return false;
    var semantic_instances: std.ArrayListUnmanaged(u32) = .empty;
    defer semantic_instances.deinit(std.heap.c_allocator);
    semantic_instances.appendSlice(std.heap.c_allocator, current_semantics.instances) catch return false;
    semantic_instances.appendSlice(std.heap.c_allocator, entry.semantic_instances) catch return false;
    var logical_ids: std.ArrayListUnmanaged(u32) = .empty;
    defer logical_ids.deinit(std.heap.c_allocator);
    if (has_logical_topology) {
        if (cur_logical_ids) |rows| logical_ids.appendSlice(std.heap.c_allocator, rows) catch return false;
        logical_ids.appendSlice(std.heap.c_allocator, entry.logical_ids.?) catch return false;
    }
    var colors: std.ArrayListUnmanaged(u8) = .empty;
    defer colors.deinit(std.heap.c_allocator);
    colors.appendSlice(std.heap.c_allocator, cur_colors) catch return false;
    colors.appendSlice(std.heap.c_allocator, entry.colors) catch return false;

    const owned = out.toOwnedSlice(std.heap.c_allocator) catch {
        return false;
    };
    defer std.heap.c_allocator.free(owned);
    const new_count = cur_count + @as(u32, @intCast(entry.verts.len / 8));
    const ok = z3d.replaceActiveEditMesh(
        owned,
        new_count,
        z3d.logicalReplacementExactOrAbsent(
            if (has_logical_topology) logical_ids.items else null,
            new_count,
            logical_vertex_count,
        ),
    );
    if (ok) {
        model_source.setFaceGroups(groups.items);
        model_source.setFaceMaterials(materials.items);
        if (!model_source.setFaceSemantics(semantic_regions.items, semantic_instances.items)) return false;
        _ = model_source.replaceGeometrySameTriangleCount(source_out.items, new_count);
        _ = z3d.refreshPaintLayout();
        z3d.restoreFaceColorMetadata(colors.items);
        z3d.freeHiddenGroup(entry);
        _ = z3d.g_hidden_groups.orderedRemove(i);
    }
    return ok;
}

/// Distinct authored group ids in [lo, hi) that still have at least one surviving face after a
/// delete. The outliner uses this to prune each part's STORED faces down to what remains — only
/// the small id list crosses the bridge, never geometry — so a later recompose keeps the delete.
pub fn meshSurvivingGroups(lo: u32, hi: u32, out: []u32) u32 {
    if (hi <= lo) return 0;
    const span = hi - lo;
    const seen = std.heap.c_allocator.alloc(bool, span) catch return 0;
    defer std.heap.c_allocator.free(seen);
    @memset(seen, false);
    const fc = model_paint.faceCount();
    var f: u32 = 0;
    while (f < fc) : (f += 1) {
        const g = model_source.faceGroupOf(f);
        if (g != model_source.NO_FACE_GROUP and g >= lo and g < hi) seen[g - lo] = true;
    }
    var n: u32 = 0;
    var i: u32 = 0;
    while (i < span) : (i += 1) {
        if (seen[i] and n < out.len) {
            out[n] = lo + i;
            n += 1;
        }
    }
    return n;
}

// ══════════════════════════════════════════════════════════════════════════
// Model-document journal (undo/redo) + the mesh/UV ops that ride it
// ══════════════════════════════════════════════════════════════════════════
// Every committed mutation of the resident model (gizmo release, topology/part op,
// UV transform, texture import/reload) snapshots the exact pre-op domain. All entries
// carry mesh UVs and ownership; texture entries additionally carry atlas pixels; UV
// and texture entries carry the editable paint program + its stroke journal. An opaque
// JS note holds the cart's part metadata so the outliner resyncs after mesh restores.
// Undo/redo swap the live state with the top snapshot. Bounded by count AND bytes,
// oldest-first.

pub const jalloc = std.heap.c_allocator;

pub const JournalHidden = struct {
    lo: u32,
    hi: u32,
    verts: []f32,
    source_verts: []f32,
    groups: []u32,
    materials: []u32,
    semantic_regions: []u32,
    semantic_instances: []u32,
    logical_ids: ?[]u32,
    logical_vertex_count: u32,
    colors: []u8,
};
pub const JournalAtlas = struct {
    rgba: []u8,
    w: u32,
    h: u32,
};
pub const JournalSelection = struct {
    mode: mesh_edit.Mode = .none,
    vertex_ids: []u32 = &.{},
    edge_pairs: []mesh_edit.Edge = &.{},
    face_mask: []bool = &.{},

    pub fn deinit(self: *z3d.JournalSelection) void {
        if (self.vertex_ids.len > 0) z3d.jalloc.free(self.vertex_ids);
        if (self.edge_pairs.len > 0) z3d.jalloc.free(self.edge_pairs);
        if (self.face_mask.len > 0) z3d.jalloc.free(self.face_mask);
        self.* = .{};
    }
};
pub const JournalEntry = struct {
    generation: u32,
    /// Durable source rows retain imported/historical normals and UVs.  The
    /// displayed rows below carry paint-atlas UVs and are not byte-equivalent.
    source_verts: []f32,
    verts: []f32,
    count: u32,
    groups: ?[]u32,
    materials: ?[]u32,
    semantic_regions: ?[]u32,
    semantic_instances: ?[]u32,
    logical_ids: ?[]u32,
    logical_vertex_count: u32,
    semantic_table_json: ?[]u8,
    part_ranges: ?[]u32,
    part_object_ids_json: ?[]u8,
    part_object_model_id: ?[]u8,
    /// Parsed/owned alongside JSON so install never parses after mutation.
    part_object_ids: ?[][]u8,
    colors: ?[]u8,
    hidden: []z3d.JournalHidden,
    atlas: ?z3d.JournalAtlas,
    paint_state: ?*paint_program.JournalState,
    // The teaching overlay is authored model data, not disposable viewport
    // decoration. Every chronological model snapshot carries its exact live
    // membership and frozen before-image so topology undo cannot erase it.
    retopo_guide: ?mesh_edit.OwnedRetopoGuide,
    // UV mask zones are the same one-row-per-face identity channel. Glass is a
    // face reorder, so its undo/redo must restore the exact reordered mask too.
    uv_zones: ?[]u16,
    paint_layout_stale: bool,
    paint_layout_revision: u64,
    note: ?[]u8,
    selection: z3d.JournalSelection,
    label: []const u8, // static string — the op that FOLLOWED this snapshot
    action_id: u32 = 0,
    action_kind: ?mesh_journal_log.ActionKind = null,
    /// Nonzero only while a mutation is in flight.  Persisted undo/redo rows
    /// never own a live lease receipt.
    mutation_lease_receipt: u64 = 0,
    mutation_lease_owned: bool = false,
};

pub fn freeJournalHidden(hidden: z3d.JournalHidden) void {
    z3d.jalloc.free(hidden.verts);
    z3d.jalloc.free(hidden.source_verts);
    z3d.jalloc.free(hidden.groups);
    z3d.jalloc.free(hidden.materials);
    z3d.jalloc.free(hidden.semantic_regions);
    z3d.jalloc.free(hidden.semantic_instances);
    if (hidden.logical_ids) |rows| z3d.jalloc.free(rows);
    z3d.jalloc.free(hidden.colors);
}

pub fn cloneJournalHidden(hidden: z3d.HiddenGroup) !z3d.JournalHidden {
    const verts = try z3d.jalloc.dupe(f32, hidden.verts);
    errdefer z3d.jalloc.free(verts);
    const source_verts = try z3d.jalloc.dupe(f32, hidden.source_verts);
    errdefer z3d.jalloc.free(source_verts);
    const groups = try z3d.jalloc.dupe(u32, hidden.groups);
    errdefer z3d.jalloc.free(groups);
    const materials = try z3d.jalloc.dupe(u32, hidden.materials);
    errdefer z3d.jalloc.free(materials);
    const semantic_regions = try z3d.jalloc.dupe(u32, hidden.semantic_regions);
    errdefer z3d.jalloc.free(semantic_regions);
    const semantic_instances = try z3d.jalloc.dupe(u32, hidden.semantic_instances);
    errdefer z3d.jalloc.free(semantic_instances);
    const logical_ids = if (hidden.logical_ids) |rows| try z3d.jalloc.dupe(u32, rows) else null;
    errdefer if (logical_ids) |rows| z3d.jalloc.free(rows);
    const colors = try z3d.jalloc.dupe(u8, hidden.colors);
    return .{
        .lo = hidden.lo,
        .hi = hidden.hi,
        .verts = verts,
        .source_verts = source_verts,
        .groups = groups,
        .materials = materials,
        .semantic_regions = semantic_regions,
        .semantic_instances = semantic_instances,
        .logical_ids = logical_ids,
        .logical_vertex_count = hidden.logical_vertex_count,
        .colors = colors,
    };
}

pub fn cloneHiddenGroup(hidden: z3d.JournalHidden) !z3d.HiddenGroup {
    const verts = try z3d.jalloc.dupe(f32, hidden.verts);
    errdefer z3d.jalloc.free(verts);
    const source_verts = try z3d.jalloc.dupe(f32, hidden.source_verts);
    errdefer z3d.jalloc.free(source_verts);
    const groups = try z3d.jalloc.dupe(u32, hidden.groups);
    errdefer z3d.jalloc.free(groups);
    const materials = try z3d.jalloc.dupe(u32, hidden.materials);
    errdefer z3d.jalloc.free(materials);
    const semantic_regions = try z3d.jalloc.dupe(u32, hidden.semantic_regions);
    errdefer z3d.jalloc.free(semantic_regions);
    const semantic_instances = try z3d.jalloc.dupe(u32, hidden.semantic_instances);
    errdefer z3d.jalloc.free(semantic_instances);
    const logical_ids = if (hidden.logical_ids) |rows| try z3d.jalloc.dupe(u32, rows) else null;
    errdefer if (logical_ids) |rows| z3d.jalloc.free(rows);
    const colors = try z3d.jalloc.dupe(u8, hidden.colors);
    return .{
        .lo = hidden.lo,
        .hi = hidden.hi,
        .verts = verts,
        .source_verts = source_verts,
        .groups = groups,
        .materials = materials,
        .semantic_regions = semantic_regions,
        .semantic_instances = semantic_instances,
        .logical_ids = logical_ids,
        .logical_vertex_count = hidden.logical_vertex_count,
        .colors = colors,
    };
}
pub const JOURNAL_CAP = 32;
pub const JOURNAL_BYTE_BUDGET: usize = 192 * 1024 * 1024;
// UV inspection/import is cart-capped at 32 MiB; leave headroom for native
// callers while refusing a single texture snapshot that could consume the
// entire resident journal budget by itself.
pub const JOURNAL_ATLAS_BYTE_CAP: usize = 64 * 1024 * 1024;
pub const MESH_ACTION_CAP: usize = 128;
pub const MeshActionEvent = mesh_journal_log.ActionEvent;
